export const getReceivePayfastItnUrl = () => {




  return `/api/payments/payfast/itn`
}

/**
 * Server-side verification is required before any ticket is issued.
 * @summary Receive and verify a PayFast sandbox ITN notification
 */
export const receivePayfastItn = async (payfastItnInput: PayfastItnInput, options?: Parameters<typeof customFetch>[1]): Promise<void> => {
    const formUrlEncoded = new URLSearchParams();
if(payfastItnInput.m_payment_id !== undefined) {
 formUrlEncoded.append(`m_payment_id`, payfastItnInput.m_payment_id);
 }
if(payfastItnInput.pf_payment_id !== undefined) {
 formUrlEncoded.append(`pf_payment_id`, payfastItnInput.pf_payment_id);
 }
if(payfastItnInput.payment_status !== undefined) {
 formUrlEncoded.append(`payment_status`, payfastItnInput.payment_status);
 }
if(payfastItnInput.amount_gross !== undefined) {
 formUrlEncoded.append(`amount_gross`, payfastItnInput.amount_gross);
 }
if(payfastItnInput.signature !== undefined) {
 formUrlEncoded.append(`signature`, payfastItnInput.signature);
 }

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<void>(getReceivePayfastItnUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', ...getHeaders(options?.headers) },
    body: formUrlEncoded
  }
);}





